"""Custom connector framework / Universal Connector Studio.

Lets Humisense define connectors for customer-specific and proprietary
applications without shipping code.  A definition is *declarative* - auth,
resources, pagination, mapping, SQL query templates - and is validated and
reviewed before it can be used.

Governance
----------
* Definitions are versioned and tenant-scoped.
* A definition moves draft -> pending_review -> approved -> published.
  Only ``published`` definitions can back a live connection.
* AI may *draft* a definition (a suggestion), but nothing generated by AI is
  executed automatically.  Publishing requires human review and passes schema
  validation plus a sandbox connection test.
* No arbitrary code is ever executed: adapters interpret a constrained schema.
"""

from __future__ import annotations

import uuid
from typing import Any

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.connectors.registry import registry
from app.core.errors import NotFoundError, ValidationError
from app.db import models
from app.schemas.contracts import AdapterKind, ValidationResult

_ADAPTER_CONNECTOR = {
    AdapterKind.REST: "universal_rest",
    AdapterKind.GRAPHQL: "universal_graphql",
    AdapterKind.SQL: "universal_sql",
    AdapterKind.FILE: "universal_file",
    AdapterKind.SFTP: "universal_file",
    AdapterKind.WEBHOOK: "universal_webhook",
}

_REVIEW_FLOW = {
    "draft": {"pending_review"},
    "pending_review": {"approved", "rejected"},
    "approved": {"published"},
    "rejected": {"draft"},
    "published": set(),
}


class CustomConnectorService:
    def __init__(self, session: Session) -> None:
        self.session = session

    def validate(self, adapter_kind: AdapterKind, definition: dict[str, Any]) -> ValidationResult:
        connector_id = _ADAPTER_CONNECTOR.get(adapter_kind)
        if connector_id is None:
            return ValidationResult(
                valid=False,
                errors=[f"Adapter kind '{adapter_kind.value}' is not supported for custom connectors."],
            )
        try:
            definition_cls = registry.get_definition(connector_id)
        except NotFoundError:
            return ValidationResult(valid=False, errors=["Adapter is not available."])

        # Structural checks independent of the adapter runtime.
        errors: list[str] = []
        warnings: list[str] = []
        if not isinstance(definition, dict):
            return ValidationResult(valid=False, errors=["Definition must be a JSON object."])
        if definition.get("write_enabled"):
            warnings.append("Write operations are disabled by default and require explicit approval.")
        if adapter_kind == AdapterKind.SQL:
            from app.connectors.adapters.sql_adapter import validate_read_only_sql

            for idx, query in enumerate(definition.get("queries", [])):
                result = validate_read_only_sql(str(query.get("sql", "")))
                errors.extend(f"queries[{idx}]: {e}" for e in result.errors)
        if adapter_kind in {AdapterKind.REST, AdapterKind.GRAPHQL}:
            auth = definition.get("auth") or {}
            if auth.get("type") in {None, "none"}:
                warnings.append("No authentication configured; only public endpoints can be used.")
        if connector_id and not errors:
            # Delegate deeper validation to the adapter's own rules.
            warnings.append(f"Validated against '{definition_cls.display_name}' contract.")
        return ValidationResult(valid=not errors, errors=errors, warnings=warnings)

    def create_definition(
        self,
        tenant_id: str,
        *,
        name: str,
        adapter_kind: AdapterKind,
        definition: dict[str, Any],
        created_by: str | None = None,
        generated_by_ai: bool = False,
    ) -> models.CustomConnectorDefinitionRow:
        if not name:
            raise ValidationError("name is required.")
        report = self.validate(adapter_kind, definition)
        if generated_by_ai:
            report.warnings.append(
                "Drafted with AI assistance. Review, validate and sandbox-test before publishing."
            )
        latest = self.session.execute(
            select(models.CustomConnectorDefinitionRow)
            .where(
                models.CustomConnectorDefinitionRow.tenant_id == tenant_id,
                models.CustomConnectorDefinitionRow.name == name,
            )
            .order_by(models.CustomConnectorDefinitionRow.version.desc())
        ).scalars().first()
        version = (latest.version + 1) if latest else 1

        row = models.CustomConnectorDefinitionRow(
            id=str(uuid.uuid4()),
            tenant_id=tenant_id,
            name=name,
            adapter_kind=adapter_kind.value,
            version=version,
            definition=definition,
            review_status="draft",
            validation_report=report.model_dump(mode="json"),
            created_by=created_by,
        )
        self.session.add(row)
        self.session.flush()
        return row

    def update_definition(
        self, tenant_id: str, definition_id: str, definition: dict[str, Any]
    ) -> models.CustomConnectorDefinitionRow:
        row = self._get(tenant_id, definition_id)
        if row.review_status == "published":
            raise ValidationError("Published definitions are immutable; create a new version.")
        report = self.validate(AdapterKind(row.adapter_kind), definition)
        row.definition = definition
        row.validation_report = report.model_dump(mode="json")
        self.session.flush()
        return row

    def transition(
        self, tenant_id: str, definition_id: str, target: str, *, actor_id: str | None = None
    ) -> models.CustomConnectorDefinitionRow:
        row = self._get(tenant_id, definition_id)
        allowed = _REVIEW_FLOW.get(row.review_status, set())
        if target not in allowed:
            raise ValidationError(
                f"Cannot move definition from '{row.review_status}' to '{target}'."
            )
        if target == "approved":
            report = self.validate(AdapterKind(row.adapter_kind), row.definition)
            if not report.valid:
                raise ValidationError(
                    "Definition failed validation and cannot be approved.",
                    detail={"errors": report.errors},
                )
        row.review_status = target
        self.session.add(
            models.AuditLog(
                tenant_id=tenant_id,
                actor_id=actor_id,
                action="custom_connector_review",
                resource_type="custom_connector_definition",
                resource_id=row.id,
                detail={"from": row.review_status, "to": target},
            )
        )
        self.session.flush()
        return row

    def list_definitions(self, tenant_id: str) -> list[models.CustomConnectorDefinitionRow]:
        return list(
            self.session.execute(
                select(models.CustomConnectorDefinitionRow)
                .where(models.CustomConnectorDefinitionRow.tenant_id == tenant_id)
                .order_by(models.CustomConnectorDefinitionRow.updated_at.desc())
            ).scalars().all()
        )

    def _get(self, tenant_id: str, definition_id: str) -> models.CustomConnectorDefinitionRow:
        row = self.session.execute(
            select(models.CustomConnectorDefinitionRow).where(
                models.CustomConnectorDefinitionRow.id == definition_id,
                models.CustomConnectorDefinitionRow.tenant_id == tenant_id,
            )
        ).scalar_one_or_none()
        if row is None:
            raise NotFoundError("Custom connector definition not found.")
        return row
